    uint64_t brick_runtime_region_scan_max_ms(uint64_t requested)
    {
        const uint64_t fallback = requested == 0
                                      ? env_u64(
                                            "BMF_BRICK_RUNTIME_REGION_SCAN_MAX_MS",
                                            250,
                                            1,
                                            5000)
                                      : requested;
        return std::max<uint64_t>(1, std::min<uint64_t>(fallback, 5000));
    }

