            const uint32_t full_end = std::min<uint32_t>(max_scan, snapshot.accessible_slots);
            brick_runtime_scan_slots(
                snapshot,
                0,
                full_end,
                target_x,
                target_y,
                target_z,
                radius_sq,
                prefer_visible,
                prefer_collidable,
                resolve);
